def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    if len(s_in) != len(s_out):
        # One is longer - check if it's a simple insertion/deletion
        if len(s_in) < len(s_out):
            # Insertion case
            for i in range(len(s_out)):
                if s_in == s_out[:i] + s_out[i+1:]:
                    return (s_out[i], '', i)  # Inserted character, empty replacement, position
        else:
            # Deletion case  
            for i in range(len(s_in)):
                if s_out == s_in[:i] + s_in[i+1:]:
                    return (s_in[i], '', i)  # Deleted character, empty replacement, position

    # Check for substitution
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            return (s_in[i], s_out[i], i)  # Old char, new char, position

    # If we reach here and lengths differ, it's an insertion at end
    if len(s_in) < len(s_out):
        return (s_out[-1], '', len(s_in))
    elif len(s_in) > len(s_out):
        return (s_in[-1], '', len(s_out))

    return ('', '', -1)  # No difference

